--------------------------------------------------------
--  DDL for Procedure ACTU_CCOSTOS
--------------------------------------------------------
set define off;

  CREATE OR REPLACE NONEDITIONABLE PROCEDURE "LDRSUMINISTROS"."ACTU_CCOSTOS" (Fec_Ini In number) As

  arch_ent   utl_file.file_type;
  arch_log   utl_file.file_type;
  v_ruta     varchar2(100);
  v_archivo1 varchar2(30);
  v_archivo2 varchar2(30);
  valor      number;
  cantidad   number;
  ws_texto   varchar2(500);
  wusuario   varchar2(500);
  pos        number(4);  
  wk_dia     varchar2(10) ;
  wk_dia2     varchar2(10) ;
  wk_fhoy    date;  
  wk_reg_ent varchar2(1002);
  ws_ident   varchar2(01);
  ws_id_cc   varchar2(04);
  ws_cc_desc varchar2(20);
  ws_cc_esta varchar2(01);
  ws_cc_dir1 varchar2(100);
  ws_cc_dir2 varchar2(20);
  ws_cc_id_prov varchar2(02);
  ws_cc_prov varchar2(20);
  ws_cc_tel  varchar2(10);
  wtb_id          varchar2(4);
  wtb_descripcion varchar2(20);
  wtb_direccion1  varchar2(50);
  wtb_direccion2  varchar2(50);
  wtb_direccion3  varchar2(50);
  wtbl_telefono   varchar2(12);
  wtbl_fec_baja   varchar2(12);
  wtbl_estado   varchar2(1);
  wtbl_cc_prov varchar2(20);
  registro   varchar2(500);
  wtbl_insert   varchar2(1);
  

begin

  select sysdate into wk_fhoy from dual;
  
  wk_dia  := to_char(wk_fhoy,'YYYYMMDD');
  
  wk_dia2 := to_char(wk_fhoy,'DD/MM/YYYY');

--  v_ruta := '/prod/jp00/utlfile/transf_OP';
  v_ruta := '/prod/jp00/utlfile/transf_VD';

  v_archivo1 := 'cencoste.seq';
  
  arch_ent   := UTL_FILE.FOPEN(v_ruta, v_archivo1, 'r');
  arch_log   := UTL_FILE.FOPEN(v_ruta, 'LOG_ACT_CC.txt', 'w');  

  UTL_FILE.PUT_LINE (arch_log, wk_dia);
  
  LOOP
    begin
      wtbl_insert := 'F';
      UTL_FILE.GET_LINE (arch_ent , wk_reg_ent );
      exception
        when no_data_found then
      exit;
      when others then
        begin
          registro := 'ERROR EN ENTRADA de DATOS (ENG_FOGAR.txt)' ;
          UTL_FILE.PUT_LINE ( arch_log , registro );
          exit;
        end;
    end;
    ws_ident   := substr ( wk_reg_ent, 1, 1 ) ;
    ws_id_cc   := substr ( wk_reg_ent, 2, 4 ) ;
    ws_cc_desc := substr ( wk_reg_ent, 8, 20 ) ;
    ws_cc_esta := substr ( wk_reg_ent, 29, 1 ) ;
    ws_cc_dir1 := substr ( wk_reg_ent, 56, 50 ) ;
    ws_cc_dir2 := substr ( wk_reg_ent, 156, 20 ) ;
    ws_cc_id_prov := substr ( wk_reg_ent, 176, 2 ) ;
    ws_cc_tel  := substr ( wk_reg_ent, 178, 10 ) ;
    ws_cc_prov := 
      Case (ws_cc_id_prov) 
        when '01' then 'CAPITAL FEDERAL'
        when '02' then 'BUENOS AIRES'
        when '03' then 'CATAMARCA'
        when '04' then 'CORDOBA'
        when '05' then 'CORRIENTES'
        when '06' then 'CHACO'
        when '07' then 'CHUBUT'
        when '08' then 'ENTRE RIOS'
        when '09' then 'FORMOSA'
        when '10' then 'JUJUY'
        when '11' then 'LA PAMPA'
        when '12' then 'LA RIOJA'
        when '13' then 'MENDOZA'
        when '14' then 'MISIONES'
        when '15' then 'NEUQUEN'
        when '16' then 'RIO NEGRO'
        when '17' then 'SALTA'
        when '18' then 'SAN JUAN'
        when '19' then 'SAN LUIS'
        when '20' then 'SANTA CRUZ'
        when '21' then 'SANTA FE'
        when '22' then 'SGO.DEL ESTERO'
        when '23' then 'TUCUMAN'
        when '40' then 'T. DEL FUEGO'
    end;   
    
    if (ws_ident = 2) then
        begin
          begin
          select ID, DESCRIPCION, DIRECCION1, DIRECCION2, DIRECCION3, TELEFONO, FE_BAJA
            into ws_id_cc, wtb_descripcion, wtb_direccion1, wtb_direccion2, wtbl_cc_prov, wtbl_telefono, wtbl_fec_baja
            from SUM_CENTRO_COSTOS
           where ID = ws_id_cc;
           if (wtbl_fec_baja is null) then
             wtbl_estado := 'A';
           else 
             wtbl_estado := 'B';          
           end if;
           UTL_FILE.PUT_LINE ( arch_log ,  ws_id_cc || '-' || wtbl_cc_prov  || '-' || ws_cc_prov);
           exception
              when no_data_found then
              begin
                    wtb_direccion1,wtb_direccion2,ws_cc_prov,ws_cc_tel,null,null);
                UTL_FILE.PUT_LINE ( arch_log , 'INSERT ' || ws_id_cc );
                wtbl_insert := 'T';
              end;        
            end;  

        UTL_FILE.PUT_LINE ( arch_log , 'UPDATE ' || ws_id_cc  || '-' ||  wtbl_insert  || '-' || wtbl_cc_prov  || '-' || ws_cc_prov);
      
        if  (wtbl_insert = 'F') and (
            (wtb_descripcion <> ws_cc_desc) OR
            (wtb_direccion1 <> ws_cc_dir1) OR
            (wtb_direccion2 <> ws_cc_dir2) OR  
            (wtbl_cc_prov <> ws_cc_prov) OR
            (wtbl_telefono <> ws_cc_tel) OR
            (wtbl_estado <> ws_cc_esta)) then
            BEGIN
              UPDATE SUM_CENTRO_COSTOS 
                SET DESCRIPCION = ws_cc_desc,
                    DIRECCION1 = trim(ws_cc_dir1),
                     DIRECCION2 = trim(ws_cc_dir2),
                     DIRECCION3 = ws_cc_prov, 
                     TELEFONO = ws_cc_tel,
                     USR_MOD = 'BATCH',
                     FE_MOD = wk_dia2
               WHERE ID = ws_id_cc; 
               exception 
                  when others then
                    UTL_FILE.PUT_LINE ( arch_log , 'ERROR UPDATE ' || ws_id_cc );                
            END;
        end if;

        UTL_FILE.PUT_LINE ( arch_log , ws_id_cc || '-' || wtbl_estado || '=' || ws_cc_esta);
        
        if  (wtbl_estado <> ws_cc_esta) then
            BEGIN
            UPDATE SUM_CENTRO_COSTOS 
               SET USR_BAJA = 'BATCH',
                   FE_BAJA = wk_dia2
             WHERE ID = ws_id_cc;
             exception 
                when others then
                  UTL_FILE.PUT_LINE ( arch_log , 'ERROR UPDATE ' || ws_id_cc );                
            UTL_FILE.PUT_LINE ( arch_log , 'DELETE ' || ws_id_cc );   
            END;
        end if;
      end;
    end if;
  END LOOP;

  commit;
  UTL_FILE.FCLOSE(arch_log);
  UTL_FILE.FCLOSE(arch_ent);

end;

/
--------------------------------------------------------
--  DDL for Procedure ACTU_EMPLEADOS
--------------------------------------------------------
set define off;

  CREATE OR REPLACE NONEDITIONABLE PROCEDURE "LDRSUMINISTROS"."ACTU_EMPLEADOS" (Fec_Ini In number) As

  arch_ent   utl_file.file_type;
  arch_log   utl_file.file_type;
  v_ruta     varchar2(100);
  v_archivo1 varchar2(30);
  v_archivo2 varchar2(30);
  valor      number;
  cantidad   number;
  ws_texto   varchar2(500);
  wusuario   varchar2(500);
  pos        number(4);  
  wk_dia     varchar2(10) ;
  wk_dia2     varchar2(10) ;
  wk_fhoy    date;  
  wk_reg_ent    varchar2(1002);

/*
  wkt_id_usr    varchar2(08);
  wkt_apellido  varchar2(75);
  wkt_id_cco    varchar2(04);
  wkt_id_nvl    varchar2(02);
  wkt_mail      varchar2(200);
  wkt_legajo    varchar2(08);
  wkt_id_ctb    varchar2(04); */

  ws_id_legajo  varchar2(08);
  ws_apellido   varchar2(50);
  ws_id_ccosto  varchar2(08);
  ws_desc_ccos  varchar2(100);
  ws_id_unidad  varchar2(08);
  ws_desc_unid  varchar2(100);
  ws_fec_antig  varchar2(10);  
  ws_id_puesto  varchar2(08);  
  ws_id_cuenta  varchar(25);
  ws_usr_corpo  varchar(8);
  ws_email      varchar(200);
  ws_id_nivel   varchar(02);
  ws_id_emplea  varchar(15);
  ws_fec_baja   varchar2(10);
  ws_conta_ccos varchar2(100);

  wkt_id_legajo  varchar2(08);
  wkt_apellido   varchar2(50);
  wkt_id_ccosto  varchar2(08);
  wkt_id_area   varchar2(08);
  wkt_desc_are  varchar2(100);
  wkt_id_puest  varchar2(08);
  wkt_desc_pue  varchar2(100);  
  wkt_id_sect   varchar2(01);
  wkt_desc_sec  varchar2(100); 
  wkt_factulad  varchar2(10);  
  wkt_email      varchar(200);
  wkt_nombre     varchar(02);
  


  registro   varchar2(500);
  wtbl_insert   varchar2(1);
  

begin

  select sysdate into wk_fhoy from dual;
  
  wk_dia  := to_char(wk_fhoy,'YYYYMMDD');
  
  wk_dia2 := to_char(wk_fhoy,'DD/MM/YYYY');

--  v_ruta := '/prod/jp00/utlfile/transf_OP';
  v_ruta := '/prod/jp00/utlfile/transf_VD';

  v_archivo1 := 'emple.txt';
  
  arch_ent   := UTL_FILE.FOPEN(v_ruta, v_archivo1, 'r');
  arch_log   := UTL_FILE.FOPEN(v_ruta, 'LOG_SUMI_EMP.txt', 'w');  

  UTL_FILE.PUT_LINE (arch_log, wk_dia);
  
  LOOP
    begin
      wtbl_insert := 'F';
      UTL_FILE.GET_LINE (arch_ent , wk_reg_ent );
      exception
        when no_data_found then
      exit;
      when others then
        begin
          registro := 'ERROR EN ENTRADA de DATOS (SUMI_EMP.txt)' ;
          UTL_FILE.PUT_LINE ( arch_log , registro );
          exit;
        end;
    end;

    ws_id_legajo   := trim( substr ( wk_reg_ent, 264, 08 )) ;
    ws_apellido    := trim( substr ( wk_reg_ent, 113, 50 )) ;
    ws_id_ccosto   := trim( substr ( wk_reg_ent,  04, 04 )) ;
    ws_desc_ccos   := trim( substr ( wk_reg_ent,  08, 40 )) ;
    ws_id_unidad   := trim( substr ( wk_reg_ent,  48, 05 )) ;
    ws_desc_unid   := trim( substr ( wk_reg_ent,  63, 40 )) ;
    ws_fec_antig   := substr ( wk_reg_ent, 188, 08 ) ;
    ws_id_puesto   := substr ( wk_reg_ent, 1, 1 ) ;  
    ws_id_cuenta   := substr ( wk_reg_ent, 198, 14 ) ;
    ws_id_emplea   := substr ( wk_reg_ent, 477, 06 ) ;
    ws_email       := trim( substr ( wk_reg_ent, 274, 200 )) ;
    ws_id_nivel    := trim( substr ( wk_reg_ent, 475, 02 )) ;
    ws_fec_baja    := substr ( wk_reg_ent, 487, 08 ) ;
    ws_conta_ccos  := substr ( wk_reg_ent, 495, 04 ) ;   
    
    UTL_FILE.PUT_LINE ( arch_log , 'DATOS ' || '-' || ws_id_ccosto || '-' || ws_desc_ccos
    || '-' || ws_id_legajo || '-' || ws_apellido  || '-' || ws_id_unidad || '-' || ws_desc_unid
    || '-' || ws_fec_antig || '-' || ws_id_puesto  || '-' || ws_id_cuenta || '-' || ws_id_emplea
    || '-' || ws_email || '-' || ws_id_nivel  || '-' || ws_fec_baja || '-' || ws_conta_ccos );

      begin
      select LEGAJO, APELLIDO, COD_AREA, COD_PUESTO, COD_SECTOR, DESC_AREA, DESC_PUESTO, DESC_SECTOR, EMAIL, CENTRO_COSTOS_ID
        into wkt_id_legajo, wkt_apellido, wkt_id_area, wkt_id_puest, wkt_id_sect, wkt_desc_are, wkt_desc_pue, wkt_desc_sec, wkt_email, wkt_id_ccosto
        from SUM_USUARIO
       where LEGAJO = ws_id_legajo;

       exception
          when no_data_found then
          begin
            UTL_FILE.PUT_LINE ( arch_log , 'INSERT ' || ws_id_legajo );
            wtbl_insert := 'T';
          end;        
        end;  

      UTL_FILE.PUT_LINE ( arch_log , 'INSERT' );

      if  (wtbl_insert = 'F') and (
          (wkt_apellido <> ws_apellido) OR
          (wkt_id_area <> ws_id_unidad) OR
          (wkt_desc_are <> ws_desc_unid) OR  
          (wkt_id_puest <> ws_id_puesto) OR
          (wkt_email <> ws_email) OR
          (wkt_id_ccosto <> ws_id_ccosto)) then
          BEGIN
          UPDATE SUM_USUARIO 
            SET APELLIDO = ws_apellido,
                COD_AREA = ws_id_unidad,
                 DESC_AREA = ws_desc_unid,
                 COD_PUESTO = ws_id_puesto, 
                 EMAIL = ws_email,
                 CENTRO_COSTOS_ID = ws_id_ccosto
           WHERE LEGAJO = ws_id_legajo; 
           exception 
              when others then
                UTL_FILE.PUT_LINE ( arch_log , 'ERROR UPDATE ' || ws_id_legajo );                
          END;
        END IF;
        

  END LOOP;

  commit;
  UTL_FILE.FCLOSE(arch_log);
  UTL_FILE.FCLOSE(arch_ent);

end;

/
